import{_ as e,o as i,c as o,ae as n}from"./chunks/framework.BzQXgbNp.js";const m=JSON.parse('{"title":"📱 Aplicación Móvil - Manual Técnico","description":"","frontmatter":{},"headers":[],"relativePath":"app-movil/index.md","filePath":"app-movil/index.md"}'),r={name:"app-movil/index.md"};function s(t,a,l,d,c,p){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="📱-aplicacion-movil-manual-tecnico" tabindex="-1">📱 Aplicación Móvil - Manual Técnico <a class="header-anchor" href="#📱-aplicacion-movil-manual-tecnico" aria-label="Permalink to &quot;📱 Aplicación Móvil - Manual Técnico&quot;">​</a></h1><h2 id="🛠️-arquitectura-y-tecnologias" tabindex="-1">🛠️ Arquitectura y Tecnologías <a class="header-anchor" href="#🛠️-arquitectura-y-tecnologias" aria-label="Permalink to &quot;🛠️ Arquitectura y Tecnologías&quot;">​</a></h2><p>La aplicación móvil de la A.C.D. Los Locos está desarrollada bajo la versión 2 del ecosistema de la peña, empleando un stack híbrido avanzado orientado a la modularidad, reactividad asíncrona viva y rendimiento nativo en hardware móvil:</p><ul><li><p>Framework Web: Angular v20, adoptando una arquitectura basada estrictamente en componentes Standalone y reactividad nativa.</p></li><li><p>Diseño de Interfaz: Ionic Framework v8, explotando componentes web optimizados para interfaces móviles de alta densidad.</p></li><li><p>Capa Nativa: Capacitor, actuando como el puente de abstracción cross-platform para el empaquetado y acceso a APIs de iOS y Android.</p></li><li><p>Base de Datos y Sesiones: SDK Modular de Firebase, integrando Cloud Firestore para sincronización offline/online, Firebase Auth para pasarelas de inicio de sesión y Firebase Cloud Messaging (FCM) para la distribución de alertas push.</p></li></ul><hr><h2 id="📂-estructura-de-paginas-y-enrutado" tabindex="-1">📂 Estructura de Páginas y Enrutado <a class="header-anchor" href="#📂-estructura-de-paginas-y-enrutado" aria-label="Permalink to &quot;📂 Estructura de Páginas y Enrutado&quot;">​</a></h2><p>El sistema implementa una arquitectura de enrutamiento modular desacoplada a través del archivo maestro src/app/app.routes.ts. Las vistas se encuentran agrupadas por dominios lógicos y características funcionales de la siguiente manera:</p><p>src/app/features/</p><ul><li><p>auth/pages/login/: Pantalla controladora para la autenticación de credenciales primarias de acceso.</p></li><li><p>auth/pages/complete-profile/: Formulario civil de onboarding obligatorio para los nuevos miembros.</p></li><li><p>auth/pages/invite/: Vista administrativa para la expedición de correos electrónicos de invitación a nuevos aspirantes.</p></li><li><p>auth/pages/pending-approval/: Pantalla de retención y bloqueo para cuentas a la espera de validación por la directiva.</p></li><li><p>events/pages/events/: Listado general de convocatorias publicadas por la peña.</p></li><li><p>events/pages/event-detail/: Ficha de detalle, control de aforo reactivo e inscripción a asambleas.</p></li><li><p>events/pages/event-guests/: Módulo operativo de gestión de pases y acompañantes para socios solventes.</p></li><li><p>events/pages/event-passes/: Tablero principal de visualización de abonos y pases válidos para hoy de la peña.</p></li><li><p>events/pages/event-scan/: Terminal operativo de validación física de códigos QR para el personal en puerta.</p></li><li><p>home/pages/home/: Dashboard unificado con accesos directos contextuales según el rol.</p></li><li><p>users/pages/gest-user/: Catálogo administrativo para la auditoría de perfiles y censo general.</p></li><li><p>users/pages/mantenimiento-cuotas/: Panel de tesorería para la visualización y edición de estados financieros por lote.</p></li><li><p>users/pages/user-detail/: Ficha atómica y encapsulada del usuario dividida en pestañas de auditoría.</p></li></ul><hr><h2 id="🔐-guardianes-de-acceso-guards" tabindex="-1">🔐 Guardianes de Acceso (Guards) <a class="header-anchor" href="#🔐-guardianes-de-acceso-guards" aria-label="Permalink to &quot;🔐 Guardianes de Acceso (Guards)&quot;">​</a></h2><p>Para blindar el perímetro de navegación y las vistas internas ante solicitudes ilegítimas o estados inconsistentes, se emplean guardianes reactivos bajo la ruta src/app/features/auth/guards/:</p><h3 id="_1-auth-guard-ts" tabindex="-1">1. auth.guard.ts <a class="header-anchor" href="#_1-auth-guard-ts" aria-label="Permalink to &quot;1. auth.guard.ts&quot;">​</a></h3><p>Garantiza que exista una sesión activa en Firebase Auth. Adicionalmente, se conecta en vivo a Firestore para evaluar el ciclo de vida real del perfil: retiene obligatoriamente a los usuarios en /pending-approval si su estado es PENDING_APPROVAL, y bloquea el acceso redirigiendo al Login si la cuenta pasa a estar INACTIVE, cerrando de forma proactiva las escuchas de datos abiertas.</p><h3 id="_2-role-guard-ts" tabindex="-1">2. role.guard.ts <a class="header-anchor" href="#_2-role-guard-ts" aria-label="Permalink to &quot;2. role.guard.ts&quot;">​</a></h3><p>Implementa el Control de Acceso Basado en Roles (RBAC). Utiliza el documento hidratado del usuario para verificar las jerarquías de UserRole y restringir de forma estricta las rutas de administración general (/gest-user) o tesorería (/mantenimiento-cuotas) exclusivamente a los perfiles ADMINISTRADOR o DIRECTIVA, abortando y redirigiendo a la Home ante intentos de intrusión.</p><hr><h2 id="🛠️-componentes-operativos-clave-y-flujos-de-ui" tabindex="-1">🛠️ Componentes Operativos Clave y Flujos de UI <a class="header-anchor" href="#🛠️-componentes-operativos-clave-y-flujos-de-ui" aria-label="Permalink to &quot;🛠️ Componentes Operativos Clave y Flujos de UI&quot;">​</a></h2><h3 id="_1-panel-de-control-de-cuotas-en-lote-mantenimientocuotaspage" tabindex="-1">1. Panel de Control de Cuotas en Lote (MantenimientoCuotasPage) <a class="header-anchor" href="#_1-panel-de-control-de-cuotas-en-lote-mantenimientocuotaspage" aria-label="Permalink to &quot;1. Panel de Control de Cuotas en Lote (MantenimientoCuotasPage)&quot;">​</a></h3><p>Componente de alta densidad diseñado para simplificar las tareas de tesorería del club sin sobrecargar la red.</p><ul><li><p>Lógica de UI Reactiva: Se inicializa permitiendo activar la selección múltiple por lote a través de un ion-checkbox. Al alterar los toggles individuales de los socios, los cambios no se envían directamente a Firestore; se encolan en caliente en el objeto de memoria local sociosModificadosTemporalmente, alterando dinámicamente el borde de las tarjetas afectadas a color azul para indicar edición.</p></li><li><p>Acción del Lote: Cuando el componente detecta que existen movimientos pendientes en la caché local, emerge reactivamente desde la base de la pantalla la barra flotante de diseño translúcido .floating-actions-bar mostrando el botón &quot;Actualizar cuota&quot;.</p></li><li><p>Persistencia: Al pulsar el botón, el componente invoca el método procesarActualizacionMasiva(), ejecutando ráfagas asíncronas controladas mediante el satélite UserFeesService. Una vez consolidada la escritura de los documentos modificados, se limpia la memoria temporal, se destruye la barra flotante y se rompe el Shadow DOM de Ionic para inyectar un ion-toast con confirmación de éxito.</p></li></ul><h3 id="_2-terminal-de-validacion-en-porteria-passescanpage" tabindex="-1">2. Terminal de Validación en Portería (PasseScanPage) <a class="header-anchor" href="#_2-terminal-de-validacion-en-porteria-passescanpage" aria-label="Permalink to &quot;2. Terminal de Validación en Portería (PasseScanPage)&quot;">​</a></h3><p>Controlador de hardware prioritario para el personal en puerta, encargado de escanear y quemar las credenciales QR de los socios e invitados mediante la cámara nativa con Capacitor o su consola de contingencia manual.</p><ul><li><p>Consola de Entrada Manual: Representada por la directiva .manual-entry-console. Integra una caja de texto reactiva vinculada mediante ngModel que mantiene bloqueado el botón de validación hasta introducir un código alfanumérico legible, proporcionando una alternativa fluida ante fallas en los sensores ópticos del dispositivo.</p></li><li><p>Lógica de Feedback Radical: Para optimizar la toma de decisiones del portero en entornos ruidosos, el método procesarAcceso() implementa respuestas extremas que alteran por completo la pantalla mediante la bandera scanStatus. Ante un pase caducado, inexistente o que ya cruzó la puerta, el terminal oculta la interfaz ordinaria y despliega a pantalla completa un layout masivo con fondo rojo (.error-bg) y un icono gigante de alerta de acceso denegado en .feedback-content. Este bloqueo visual se sincroniza por hardware disparando los motores de haptic vibration del terminal mediante Capacitor Haptics (NotificationType.Error), volviendo al estado de espera tras un retardo controlado de 2.5 segundos.</p></li></ul><hr><h2 id="⚙️-configuracion-y-compilacion-nativa-capacitor" tabindex="-1">⚙️ Configuración y Compilación Nativa (Capacitor) <a class="header-anchor" href="#⚙️-configuracion-y-compilacion-nativa-capacitor" aria-label="Permalink to &quot;⚙️ Configuración y Compilación Nativa (Capacitor)&quot;">​</a></h2><p>El nexo con las capacidades y empaquetados para tiendas móviles se centraliza en la raíz del monorrepo a través de archivos JSON de configuración estructurados.</p><h3 id="ficheros-de-configuracion-criticos" tabindex="-1">Ficheros de Configuración Críticos <a class="header-anchor" href="#ficheros-de-configuracion-criticos" aria-label="Permalink to &quot;Ficheros de Configuración Críticos&quot;">​</a></h3><ul><li><p>capacitor.config.ts: Fija de forma inmutable el identificador de paquete oficial de la peña (appId: &#39;com.adcloslocos.app&#39;), el nombre descriptivo de la app nativa y el directorio de salida web de compilación (webDir: &#39;www&#39;).</p></li><li><p>ionic.config.json: Administra las tareas de integración global del CLI de Ionic, declarando el tipo de proyecto como angular-standalone.</p></li></ul><h3 id="comandos-de-despliegue-y-sincronizacion" tabindex="-1">Comandos de Despliegue y Sincronización <a class="header-anchor" href="#comandos-de-despliegue-y-sincronizacion" aria-label="Permalink to &quot;Comandos de Despliegue y Sincronización&quot;">​</a></h3><p>Para trasladar de manera correcta las mutaciones aplicadas sobre los componentes web en Angular hacia los contenedores de desarrollo de Apple Xcode o Android Studio, se ejecutan las siguientes instrucciones secuenciales desde la consola del proyecto:</p><ol><li><p>Compilar los artefactos web optimizados aplicando árboles de sacudida y compresión en producción: ng build --configuration=production</p></li><li><p>Sincronizar el directorio compilado, variables de entorno y plugins nativos del hardware móvil hacia los SDKs de iOS y Android: npx cap sync</p></li><li><p>Inicializar las herramientas de compilación nativa de la plataforma correspondiente para la firma del binario o pruebas en emulador físico: npx cap open android npx cap open ios</p></li></ol><hr>',33)])])}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
